// 创建时间的三种展示互斥：
//   1. 字段缺失、值为 null 或空字符串：单元格保持空白，且没有悬浮说明；
//   2. 能解析成有效日期：按浏览器本地时区显示 YYYY-MM-DD HH:mm:ss，月日时分秒
//      补足两位；带时区偏移的字符串按其实际时刻换算到本地，而不是把原串里的
//      时分直接当本地时间；悬浮说明保留接口返回的原始时间字符串；
//   3. 非空但无法解析的字符串：逐字按原文显示，不删字符、不替换成当前时间，
//      也不附加日期悬浮说明（由调用方以 textContent 赋值，尖括号等只作文字）。
// 返回 null 表示“留空且无说明”；对象/数组等异常字段在到达这里之前已由
// isAbnormalField 拦下，本函数只处理原始值（字符串、数字、布尔值等）。
function formatTime(value) {
  if (value === null || value === undefined) return null;
  var raw = String(value);
  if (raw === '') return null;
  var d = new Date(value);
  if (!isNaN(d.getTime())) {
    var pad = function (n) { return String(n).padStart(2, '0'); };
    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    return { text: text, title: raw };
  }
  // 无法解析的非空值：原文作为普通文本返回，不带任何悬浮说明。
  return { text: raw };
}

